def erdos_renyi_graph(n=100, p=0.5, seed=1234):
    "Returns an Erdos-Renyi random graph."
    np.random.seed(seed)
    edges = itertools.combinations(range(n), 2)
    G = nx.Graph()

    for e in edges:
        if np.random.rand() < p:
            G.add_edge(*e)
    return G
